import json

def shapes(g, top):
    # connected components of nonzero, excluding 5-divider
    H,W=len(g),len(g[0])
    seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen and g[r][c]!=5:
                col=g[r][c]; stack=[(r,c)]; cells=[]; seen.add((r,c))
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==col:
                            seen.add((ny,nx)); stack.append((ny,nx))
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                out.append({'col':col,'r0':min(ys),'c0':min(xs),'h':max(ys)-min(ys)+1,'w':max(xs)-min(xs)+1,
                            'pat':[[int((y,x) in cells) for x in range(min(xs),max(xs)+1)] for y in range(min(ys),max(ys)+1)]})
    return out

def transform(g):
    shs=shapes(g,None)
    bot=[s for s in shs if s['r0']>5][0]
    tops=[s for s in shs if s['r0']<5]
    sel=max(tops,key=lambda s:s['c0'])  # rightmost top shape
    H=9; out=[[0]*len(g[0]) for _ in range(H)]
    for y in range(bot['h']):
        for x in range(bot['w']):
            if bot['pat'][y][x]:
                out[5+y][bot['c0']+x]=bot['col']
    top_shift = 5-bot['h']-1  # rows 2..4 when bot h=3
    for y in range(sel['h']):
        for x in range(sel['w']):
            if sel['pat'][y][x]:
                out[top_shift+y][bot['c0']+x]=sel['col']
    return out

